#!/usr/bin/env python3
"""
Regenerates docs/DOUBT_CODES.md from DoubtCode enum and metadata registry.
Guarantees docs/DOUBT_CODES.md never goes stale.
"""

import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(REPO_ROOT / "backend"))

from app.doubt.codes import DoubtCode
from app.doubt.messages import DOUBT_REGISTRY


def generate_markdown() -> str:
    lines = [
        "# KTU Activity Points Checker — Doubt Code Register",
        "",
        "> **Auto-generated from `app.doubt.codes.DoubtCode` and `app.doubt.messages.DOUBT_REGISTRY`.**",
        "> Any modification to doubt logic must be reflected in code; do not edit this file directly.",
        "",
        "Under the non-negotiable Prime Directive (`agent.md` §1), the default verdict for every",
        "certificate is `DOUBT`. If any doubt code fires, the points are treated as 0 for Confirmed",
        "and placed in Pending points for SFA / reviewer resolution.",
        "",
        "## Summary by Family",
        "",
        "| Family | Description | Code Range |",
        "|---|---|---|",
        "| **Quality (Q)** | Document legibility, resolution, blur, skew, completeness | Q-01 – Q-06 |",
        "| **Extraction (E)** | Data extraction agreement, grounding, name matching, date formats | E-01 – E-07 |",
        "| **Classification (C)** | Rule matching, level attribution, position ambiguity, institution tier | C-01 – C-07 |",
        "| **Eligibility (R)** | Study period window, duration requirements, issuer authority, quotas | R-01 – R-10 |",
        "| **Authenticity (F)** | Online verification, QR integrity, duplicate detection, tampering | F-01 – F-04 |",
        "| **System (S)** | Scheme mismatch, handbook ambiguities, engine integrity | S-01 – S-03 |",
        "| **Deduplication (D-DUP)** | Rule i event deduplication (winner beats participation) | D-DUP |",
        "",
        "---",
        "",
        "## Complete Register",
        "",
        "| Code | Family | Severity | Student Message | How to Resolve | Points Impact |",
        "|---|---|---|---|---|---|",
    ]

    for code in DoubtCode:
        meta = DOUBT_REGISTRY[code]
        msg = meta.message_template.replace("|", "\\|")
        resolve = meta.resolve_guidance.replace("|", "\\|")
        impact = meta.points_impact.replace("|", "\\|")
        lines.append(
            f"| `{meta.code.value}` | **{meta.family}** | `{meta.severity}` | {msg} | {resolve} | {impact} |"
        )

    lines.append("")
    return "\n".join(lines)


def main() -> None:
    output_path = REPO_ROOT / "docs" / "DOUBT_CODES.md"
    content = generate_markdown()
    with open(output_path, "w", encoding="utf-8") as f:
        f.write(content)
    print(f"✓ Successfully generated {output_path} ({len(DoubtCode)} doubt codes)")


if __name__ == "__main__":
    main()
